int mkstemp(char *pattern)
{
	int start, i;
#ifdef _WIN32
	int val = GetCurrentProcessId();
#else
	pid_t val = getpid();
#endif

	start = strlen(pattern) - 1;

	while (pattern[start] == 'X') {
		pattern[start] = '0' + val % 10;
		val /= 10;
		start--;
	}

	do {
		int fd;
		fd = open(pattern, O_RDWR | O_CREAT | O_EXCL | O_BINARY, 0600);
		if (fd >= 0 || errno != EEXIST)
			return fd;
		i = start + 1;
		do {
			if (pattern[i] == 0)
				return -1;
			pattern[i]++;
			if (pattern[i] == '9' + 1)
				pattern[i] = 'a';
			if (pattern[i] <= 'z')
				break;
			pattern[i] = 'a';
			i++;
		} while (1);
	} while (1);
}

