61: /* Some console SDKs (3DS, possibly others) handle duplicate and trailing
62:  * slashes very poorly. This function should be used to guarantee any path
63:  * created by these functions will not have these issues. */
64: static void clean_slashes(struct libxmp_path *p, size_t pos)
65: {
66: 	size_t i, j;
67: 	if (pos >= p->length)
68: 		return;
69: 
70: 	/* Normalize to /, detect duplicates */
71: 	for (i = pos; i < p->length; i++) {
72: 		if (is_slash(p->path[i])) {
73: 			p->path[i] = '/';
74: 			if (i + 1 < p->length && is_slash(p->path[i + 1])) {
75: 				break;
76: 			}
77: 		}
78: 	}
79: 	/* Clean duplicates if they exist */
80: 	for (j = i; i < p->length; ) {
81: 		if (is_slash(p->path[i])) {
82: 			p->path[j++] = '/';
83: 			i++;
84: 			while (i < p->length && is_slash(p->path[i])) {
85: 				i++;
86: 			}
87: 		} else {
88: 			p->path[j++] = p->path[i++];
89: 		}
90: 	}
91: 	/* Trim trailing slash, except at index 0 */
92: 	if (j > 1 && is_slash(p->path[j - 1])) {
93: 		j--;
94: 	}
95: 	p->path[j] = '\0';
96: 	p->length = j;
97: }
