 */
const unsigned char *hio_get_underlying_memory(HIO_HANDLE *h)
{
	switch (HIO_HANDLE_TYPE(h)) {
	case HIO_HANDLE_TYPE_FILE:
	case HIO_HANDLE_TYPE_CBFILE:
		return NULL;
	case HIO_HANDLE_TYPE_MEMORY:
		return h->handle.mem->start;
	}
	return NULL;
